local _, ns = "Curator", CuratorOctoFull

-- (1.14.0) The words of the five trees of the talents (Talents.lua), of their windows (the talents, the Darkmoon Wheel,
-- Under the counter of the reseller, the booster bar, the boosters of the inventory), of their summits (their
-- achievements and their titles of prestige), of the chest of the rerolls, and of the innkeeper redone (the rest of the
-- collector, the dish of the day, the leads of the tavern and the round, his counter, the scene of his bet), and of the
-- rubies of the quests of the game turned in. They go into the tables of Locale.lua (English keys; a missing one falls
-- back to English).
local T = ns.LocaleTables

local function Add(locale, words)
	local dst = T and T[locale]
	if not dst then
		return
	end
	for k, v in pairs(words) do
		if dst[k] == nil then
			dst[k] = v
		end
	end
end

