	["World: %d%%"] = "Monde : %d %%",
	["You can play two bets a day at the innkeepers."] = "Tu peux jouer deux paris par jour chez les taverniers.",
	["Your appraised cards bear your name on their label, seen by the other collectors in your showcase."] = "Tes cartes expertisées portent ton nom sur leur étiquette, vu des autres collectionneurs dans ta vitrine.",
	["Your bar of the world fills with all you do where an album lives: each time it is full, a booster of that album (%d%% now)."] = "Ta barre du monde se remplit de tout ce que tu fais là où vit un album : chaque fois qu'elle est pleine, un booster de cet album (%d %% pour l'instant).",
	["Your booster bar of the world fills %s faster in a zone you have not played in for 3 days."] = "Ta barre de booster du monde se remplit %s plus vite dans une zone où tu n'as pas joué depuis 3 jours.",
