	["Your showcase shows two more cards."] = "Ta vitrine montre deux cartes de plus.",
	["Your talents on it: %s."] = "Tes talents dessus : %s.",
	["Your talents were given back: %d points to place again as you like, free of charge (/curator talents)."] = "Tes talents t'ont été rendus : %d points à replacer comme tu veux, gratuitement (/curator talents).",
