	["Darling of the Faire"] = "Chouchou de la Foire",
	["The Darkmoon Wheel stopped on the booster of a dungeon, a summit of the Gambler."] = "La Roue de Sombrelune arrêtée sur le booster de donjon, un sommet du Flambeur.",
