Add("deDE", {
	["\"Between us, then. What is under my counter never was here.\""] = "„Also unter uns. Was unter meiner Theke liegt, war nie hier.“",
	["\"I may have something you are missing, rare or epic. For you, a price.\""] = "„Vielleicht habe ich etwas, das dir fehlt, selten oder episch. Für dich ein Freundschaftspreis.“",
	["\"Step right up! Darkmoon Fortune is with you: the wheel stops less often on nothing.\""] = "„Hereinspaziert! Dunkelmondglück ist mit dir: Das Rad bleibt seltener bei Nichts stehen.“",
	["\"Step right up, step right up! Once a day, the wheel of the Faire for you.\""] = "„Hereinspaziert, hereinspaziert! Einmal am Tag dreht sich das Rad des Jahrmarkts für dich.“",
	["%d levels to go"] = "Noch %d Stufen",
	["%d rubies"] = "%d Rubine",
	["%d%%"] = "%d %%",
	["%s for %s instead of %s."] = "%s für %s statt %s.",
	["%s recharges: ready in %s."] = "%s lädt sich auf: bereit in %s.",
	["%s · %s left"] = "%s · noch %s",
	["%s!"] = "%s!",
	["%s: %d%% of the album!"] = "%s: %d %% des Albums!",
	["%s: the gain of this one doubled (once a week)."] = "%s: Der Gewinn dieser Restaurierung wird verdoppelt (einmal pro Woche).",
	["%s: this one for nothing (once a week)."] = "%s: Diese Restaurierung ist kostenlos (einmal pro Woche).",
	["(%d cards you are missing)"] = "(%d Karten, die dir fehlen)",
	["/curator active: the talent to use of your tree"] = "/curator active: das einsetzbare Talent deines Baums",
	["/curator talents: your talents (from level 5)"] = "/curator talents: deine Talente (ab Stufe 5)",
	["1 level to go"] = "Noch 1 Stufe",
	["A bet takes %d copies to spare of the same card, from common to epic, of a rarity this album can match. You have none: duplicates come with the boosters, come back with some!"] = "Eine Wette braucht dieselbe Karte %d-mal als überzähliges Exemplar, von gewöhnlich bis episch, in einer Seltenheit, die dieses Album aufwiegen kann. Du hast keine: Doppelte Karten kommen mit den Boostern, komm mit ein paar wieder!",
	["A card rare at most."] = "Eine Karte, höchstens selten.",
	["A card you already have, found on a creature, gives way %s of the time to a card of the same album and rarity that you are missing."] = "Eine Karte, die du schon hast und bei einer Kreatur findest, weicht in %s der Fälle einer Karte desselben Albums und derselben Seltenheit, die dir fehlt.",
	["A case that gives a card of its lowest rank gives you back %s of the price of a key."] = "Eine Kiste, die eine Karte ihres niedrigsten Rangs gibt, erstattet dir %s des Schlüsselpreises.",
	["A contract has a %s chance to give you back one of the cards you put in it."] = "Ein Vertrag hat eine Chance von %s, dir eine der Karten zurückzugeben, die du hineingelegt hast.",
	["A copy sold to the reseller can be bought back at the same price for 3 days."] = "Ein an den Wiederverkäufer verkauftes Exemplar kann 3 Tage lang zum selben Preis zurückgekauft werden.",
	["A display you open holds one more booster %s of the time."] = "Ein Display, das du öffnest, enthält in %s der Fälle einen Booster mehr.",
	["A dungeon done (its last boss) in less than 45 minutes fills its bar with 50 points."] = "Ein Dungeon, den du in weniger als 45 Minuten abschließt (bis zu seinem letzten Boss), gibt seiner Leiste 50 Punkte.",
	["A gift you make, once confirmed, gives you %s rubies (once a day)."] = "Ein Geschenk von dir gibt dir, sobald es bestätigt ist, %s Rubine (einmal pro Tag).",
	["A quarter of everything this character earns, kept until level %d: then it all goes to your collection."] = "Ein Viertel von allem, was dieser Charakter erhält, aufbewahrt bis Stufe %d: Dann geht alles in deine Sammlung.",
	["A raid"] = "Ein Schlachtzug",
	["A revenge fills your booster bar of the world with 30 points; your Nemesis brought down, with 100."] = "Ein Racheakt gibt deiner Boosterleiste der Welt 30 Punkte; bringst du deine Nemesis zur Strecke, 100.",
	["A rumor of the tavern stays true %s more, as long as its card is not found."] = "Ein Gerücht der Taverne bleibt %s länger wahr, solange seine Karte nicht gefunden ist.",
	["A sound and a message tell you when a rare whose card you are missing is in sight."] = "Ein Ton und eine Nachricht melden dir, wenn eine seltene Kreatur in Sicht ist, deren Karte dir fehlt.",
	["A stamp of your loyalty card has a %s chance to count twice for the loyalty of its innkeeper (and his signed card)."] = "Ein Stempel deiner Treuekarte hat eine Chance von %s, für die Treue seines Gastwirts (und dessen signierte Karte) doppelt zu zählen.",
	["A summit of the tree of the Smuggler, at its seventh tier."] = "Ein Gipfel im Baum des Schmugglers, auf seiner siebten Ebene.",
	["A summit of the tree: the first time it works, an achievement and a title of prestige."] = "Ein Gipfel des Baums: Wenn er zum ersten Mal wirkt, ein Erfolg und ein Prestigetitel.",
	["A talent of the Smuggler, at the ninth tier of his tree."] = "Ein Talent des Schmugglers, auf der neunten Ebene seines Baums.",
	["A talent of the Smuggler, at the third tier of his tree."] = "Ein Talent des Schmugglers, auf der dritten Ebene seines Baums.",
	["A trade confirmed where both sides give something fills your booster bar of the world with %s points (once a day for each player, 5 players a day)."] = "Ein bestätigter Tausch, bei dem beide Seiten etwas geben, gibt deiner Boosterleiste der Welt %s Punkte (einmal pro Tag und Spieler, 5 Spieler pro Tag).",
	["A trade with a player you never traded with gives you 100 rubies (once a week)."] = "Ein Tausch mit einem Spieler, mit dem du noch nie getauscht hast, gibt dir 100 Rubine (einmal pro Woche).",
	["A tree of %d ranks, ten tiers"] = "Ein Baum mit %d Rängen, zehn Ebenen",
	["APPRAISED FOR %s"] = "BEGUTACHTET FÜR %s",
	["Active"] = "Aktiv",
	["Active, once a week: for 1 hour, the creatures of your zone give you their card three times as often. The first time an epic card or better falls during an Expedition: an achievement and a title of prestige."] = "Aktiv, einmal pro Woche: 1 Stunde lang geben dir die Kreaturen deines Gebiets ihre Karte dreimal so oft. Wenn während einer Expedition zum ersten Mal eine epische Karte oder besser fällt: ein Erfolg und ein Prestigetitel.",
	["Active: before you appraise a copy, you see the grade it would get, and you can give up without paying. Recharges in %s."] = "Aktiv: Bevor du ein Exemplar begutachten lässt, siehst du die Note, die es bekäme, und kannst verzichten, ohne zu bezahlen. Abklingzeit: %s.",
	["Active: bet your next booster: an even chance that it holds two more cards, or two fewer (one for a booster of a dungeon or a raid). Recharges in %s."] = "Aktiv: Setz deinen nächsten Booster: Mit gleicher Chance enthält er zwei Karten mehr oder zwei weniger (eine bei einem Dungeon- oder Schlachtzug-Booster). Abklingzeit: %s.",
	["Active: for %s, in your zone, the creatures whose card you are missing wear a mark in their tooltip and give their card twice as often. Recharges in %s."] = "Aktiv: %s lang tragen die Kreaturen deines Gebiets, deren Karte dir fehlt, eine Markierung in ihrem Tooltip und geben ihre Karte doppelt so oft. Abklingzeit: %s.",
	["Active: mark your target (a creature that has a card): defeat it within %s and your chance to find its card is tripled. Recharges in %s."] = "Aktiv: Markiere dein Ziel (eine Kreatur mit Karte): Besiege es innerhalb von %s, und deine Chance, seine Karte zu finden, verdreifacht sich. Abklingzeit: %s.",
	["Active: the reseller brings out from under his counter a card you are missing, rare or epic, %s cheaper than its price. Recharges in %s."] = "Aktiv: Der Wiederverkäufer holt unter seiner Theke eine Karte hervor, die dir fehlt, selten oder episch, %s günstiger als ihr Preis. Abklingzeit: %s.",
	["Adrenaline Rush"] = "Adrenalinrausch",
	["After an epic card (Hot Hand)"] = "Nach einer epischen Karte (Heiße Hand)",
	["After an epic card or better, your next two boosters: your chance of an epic card +%s."] = "Nach einer epischen Karte oder besser, in deinen nächsten zwei Boostern: deine Chance auf eine epische Karte +%s.",
	["After it: %s, its tree and your points to place."] = "Danach: %s, ein neuer Baum und deine Punkte zum Verteilen.",
	["After it: %s, your points to place again."] = "Danach: %s, deine Punkte neu zu verteilen.",
	["All"] = "Alle",
	["All (%d)"] = "Alle (%d)",
	["All the experience you earn outside the dungeons and the raids: +%s."] = "Alle Erfahrung, die du außerhalb von Dungeons und Schlachtzügen verdienst: +%s.",
	["An album of a zone that reaches 25 %%, 50 %% or 75 %% of its cards gives you %s rubies; %s at 100 %%."] = "Ein Album eines Gebiets, das 25 %%, 50 %% oder 75 %% seiner Karten erreicht, gibt dir %s Rubine; %s bei 100 %%.",
	["And one more, for a regular like you: %s, around %s."] = "Und noch eins, für Stammkunden wie dich: %s, in der Gegend von %s.",
	["Appraised, it gets exactly that. Or keep it as it is: you pay nothing."] = "Begutachtet bekommt es genau diese Note. Oder lass es, wie es ist: Du zahlst nichts.",
