	["Double or Nothing"] = "Doppelt oder nichts",
	["Double or Nothing can bet a whole display: three more boosters, or three fewer."] = "Doppelt oder nichts kann ein ganzes Display setzen: drei Booster mehr oder drei weniger.",
	["Double or Nothing leans your way: one more card won (rank 1), one card fewer lost (rank 2), a 60 %% chance to win (rank 3)."] = "Doppelt oder nichts neigt sich dir zu: eine Karte mehr gewonnen (Rang 1), eine Karte weniger verloren (Rang 2), eine Gewinnchance von 60 %% (Rang 3).",
	["Double or Nothing lost, but Nerves of Steel: it costs nothing."] = "Doppelt oder nichts verloren, aber Stahlnerven: Es kostet nichts.",
	["Double or Nothing makes you lose no card any more, but wins you one only."] = "Bei Doppelt oder nichts verlierst du keine Karte mehr, gewinnst aber nur eine.",
	["Double or Nothing recharges in %s."] = "Abklingzeit von Doppelt oder nichts: %s.",
	["Double or Nothing won on a booster of a dungeon or a raid: one more card."] = "Doppelt oder nichts, gewonnen bei einem Dungeon- oder Schlachtzug-Booster: eine Karte mehr.",
	["Double or Nothing won on a booster of a zone: 100 rubies more."] = "Doppelt oder nichts, gewonnen bei einem Gebiets-Booster: 100 Rubine mehr.",
	["Double or Nothing: a %s chance that a bet lost costs nothing."] = "Doppelt oder nichts: eine Chance von %s, dass eine verlorene Wette nichts kostet.",
	["Double or Nothing: lost, %d cards fewer."] = "Doppelt oder nichts: verloren, %d Karten weniger.",
	["Double or Nothing: lost, but Nerves of Steel kept the boosters."] = "Doppelt oder nichts: verloren, aber Stahlnerven haben die Booster gerettet.",
	["Double or Nothing: lost, one card fewer."] = "Doppelt oder nichts: verloren, eine Karte weniger.",
	["Double or Nothing: lost, three boosters fewer."] = "Doppelt oder nichts: verloren, drei Booster weniger.",
	["Double or Nothing: nothing won, nothing lost."] = "Doppelt oder nichts: nichts gewonnen, nichts verloren.",
	["Double or Nothing: the bet is taken back."] = "Doppelt oder nichts: Die Wette ist zurückgenommen.",
	["Double or Nothing: won, %d cards more!"] = "Doppelt oder nichts: gewonnen, %d Karten mehr!",
	["Double or Nothing: won, one card more!"] = "Doppelt oder nichts: gewonnen, eine Karte mehr!",
	["Double or Nothing: won, three boosters more!"] = "Doppelt oder nichts: gewonnen, drei Booster mehr!",
	["Double or Nothing: your next booster is the bet."] = "Doppelt oder nichts: Dein nächster Booster ist der Einsatz.",
	["Double or Nothing: your next booster or display is the bet."] = "Doppelt oder nichts: Dein nächster Booster oder dein nächstes Display ist der Einsatz.",
	["Each album of a zone completed gives you %s rubies."] = "Jedes vervollständigte Album eines Gebiets gibt dir %s Rubine.",
	["Each bet won at an innkeeper gives you %s rubies, each case opened %s."] = "Jede gewonnene Wette bei einem Gastwirt gibt dir %s Rubine, jede geöffnete Kiste %s.",
	["Each card appraised 8 or better gives you %s rubies."] = "Jede mit 8 oder besser begutachtete Karte gibt dir %s Rubine.",
	["Each card appraised gives you %s experience, three times as much for a 9 or a 10."] = "Jede begutachtete Karte gibt dir %s Erfahrung, dreimal so viel bei einer 9 oder 10.",
	["Each card bought from the reseller gives you back %s of its price in rubies."] = "Jede beim Wiederverkäufer gekaufte Karte gibt dir %s ihres Preises in Rubinen zurück.",
	["Each collector level: a booster to choose, for the album you want."] = "Jede Sammlerstufe: ein Booster zur Wahl, für das Album, das du willst.",
	["Each collector who looks at your showcase gives you 5 rubies (20 visitors a day at most)."] = "Jeder Sammler, der sich deine Vitrine ansieht, gibt dir 5 Rubine (höchstens 20 Besucher pro Tag).",
	["Each contract signed gives you %s experience."] = "Jeder unterzeichnete Vertrag gibt dir %s Erfahrung.",
	["Each day, a target is named to you: an elite or a rare of a zone of your level whose card you are missing. Defeat it and its card is given to you. The first time: an achievement and a title of prestige."] = "Jeden Tag wird dir ein Ziel genannt, dessen Karte dir fehlt: ein Elitegegner oder eine seltene Kreatur aus einem Gebiet deiner Stufe. Besiege es, und seine Karte gehört dir. Beim ersten Mal: ein Erfolg und ein Prestigetitel.",
	["Each day, among the cards the reseller sells, one is surely missing from your albums."] = "Jeden Tag ist unter den Karten, die der Wiederverkäufer verkauft, garantiert eine, die in deinen Alben fehlt.",
	["Each day, spin the wheel: nothing (40 %%), 150 rubies (30 %%), a booster of a zone (22 %%), two boosters of a zone (6 %%) or a booster of a dungeon (2 %%). The first time it stops on the booster of a dungeon: an achievement and a title of prestige."] = "Dreh jeden Tag das Rad: nichts (40 %%), 150 Rubine (30 %%), ein Zonen-Booster (22 %%), zwei Zonen-Booster (6 %%) oder ein Dungeon-Booster (2 %%). Wenn es zum ersten Mal beim Dungeon-Booster stehen bleibt: ein Erfolg und ein Prestigetitel.",
	["Each day, you can order from the reseller a card you are missing, epic at most, at its full price. The first time: an achievement and a title of prestige."] = "Jeden Tag kannst du beim Wiederverkäufer eine Karte bestellen, die dir fehlt, höchstens episch, zum vollen Preis. Beim ersten Mal: ein Erfolg und ein Prestigetitel.",
	["Each day, your first 5 boosters opened: a %s chance that one of their cards goes up a rarity (epic at most)."] = "Jeden Tag, bei deinen ersten 5 geöffneten Boostern: eine Chance von %s, dass eine ihrer Karten eine Seltenheitsstufe aufsteigt (höchstens episch).",
	["Each day, your first quest turned in in each zone fills its bar with %s more points."] = "Jeden Tag gibt deine erste abgegebene Quest in jedem Gebiet seiner Leiste %s Punkte mehr.",
	["Each day, your first victory over a creature whose card you are missing (rare at most), in a zone where you have less than three quarters of the cards, gives you its card. The first time: an achievement and a title of prestige."] = "Jeden Tag gibt dir dein erster Sieg über eine Kreatur, deren Karte dir fehlt (höchstens selten), in einem Gebiet, in dem du weniger als drei Viertel der Karten hast, ihre Karte. Beim ersten Mal: ein Erfolg und ein Prestigetitel.",
	["Each elite or rare whose card you find gives you %s rubies."] = "Jede Karte, die du bei einem Elitegegner oder einer seltenen Kreatur findest, gibt dir %s Rubine.",
	["Each herb, ore, skin or fish you gather gives %s points to your booster bar of the world (a creature gives 2)."] = "Jedes Mal, wenn du Kräuter, Erz, Leder oder Fisch sammelst: %s Punkte für deine Boosterleiste der Welt (eine Kreatur gibt 2).",
	["Each honorable kill fills your booster bar of the world with %s points."] = "Jeder ehrenhafte Sieg gibt deiner Boosterleiste der Welt %s Punkte.",
	["Each new combatant certified in your PvP album gives you %s rubies."] = "Jeder neue beglaubigte Kämpfer in deinem PvP-Album gibt dir %s Rubine.",
	["Each new visa of your travel passport gives you %s rubies and %s experience."] = "Jedes neue Visum in deinem Reisepass gibt dir %s Rubine und %s Erfahrung.",
	["Each rare you defeat fills your booster bar of the world with %s points."] = "Jede seltene Kreatur, die du besiegst, gibt deiner Boosterleiste der Welt %s Punkte.",
	["Each thing gathered has a %s chance to give you 25 rubies."] = "Jedes Mal, wenn du etwas sammelst, eine Chance von %s auf 25 Rubine.",
	["Each trade confirmed gives you 10 rubies (5 trades a day)."] = "Jeder bestätigte Tausch gibt dir 10 Rubine (5 Tauschgeschäfte pro Tag).",
	["Each week you open 50 boosters or more: %s rubies."] = "Jede Woche, in der du 50 Booster oder mehr öffnest: %s Rubine.",
	["Each week, the first last boss of a dungeon or boss of a raid you defeat gives you one more booster of its album."] = "Jede Woche gibt dir der erste Boss, den du besiegst (der letzte Boss eines Dungeons oder ein Boss eines Schlachtzugs), einen zusätzlichen Booster seines Albums.",
	["Each week, when you hold more than 20 000 rubies, you earn %s of them (300 at most for each rank)."] = "Jede Woche, in der du mehr als 20.000 Rubine besitzt, verdienst du %s davon (höchstens 300 pro Rang).",
	["Each week, your best appraised copy gives you %s rubies (three times as many for a 10)."] = "Jede Woche gibt dir dein am besten begutachtetes Exemplar %s Rubine (dreimal so viele bei einer 10).",
	["Each week, your first booster opened has one chance in ten to become a booster of legend: 5 cards epic or better, one of them legendary. The first time: an achievement and a title of prestige."] = "Jede Woche wird dein erster geöffneter Booster in einem von zehn Fällen zum Legendenbooster: 5 Karten, episch oder besser, eine davon legendär. Beim ersten Mal: ein Erfolg und ein Prestigetitel.",
	["Enchanter's Patience"] = "Geduld des Verzauberers",
