	["No copy sold in the last 3 days."] = "Kein Exemplar in den letzten 3 Tagen verkauft.",
	["No talent to use yet: the third tier of your tree holds one."] = "Noch kein einsetzbares Talent: Die dritte Ebene deines Baums enthält eins.",
