	["Survey runs: %s left."] = "Vermessung läuft: noch %s.",
	["Survey: for %s, the creatures of your zone whose card you are missing give it twice as often."] = "Vermessung: %s lang geben dir die Kreaturen deines Gebiets, deren Karte dir fehlt, sie doppelt so oft.",
	["Survey: its card is missing from your album (%s)."] = "Vermessung: Ihre Karte fehlt in deinem Album (%s).",
	["Terra Incognita"] = "Terra Incognita",
	["The 7th stamp of your loyalty card of the inns gives one more booster %s of the time."] = "Der 7. Stempel deiner Treuekarte gibt in %s der Fälle einen Booster mehr.",
	["The Darkmoon Wheel stops less often on nothing: %s points fewer, moved to the boosters."] = "Das Dunkelmondrad bleibt seltener bei Nichts stehen: %s Prozentpunkte weniger, zugunsten der Booster.",
	["The Great Game"] = "Das Große Spiel",
	["The Great Game: a booster of legend!"] = "Das Große Spiel: ein Legendenbooster!",
	["The achievements of PvP, of the dungeons and of the raids give %s more experience and rubies."] = "Die Erfolge für PvP, Dungeons und Schlachtzüge geben %s mehr Erfahrung und Rubine.",
	["The achievements of the albums and of exploration give %s more experience and rubies."] = "Die Erfolge für Alben und Erkundung geben %s mehr Erfahrung und Rubine.",
	["The achievements of the collection (albums complete, rarities) give %s more rubies."] = "Die Erfolge der Sammlung (vollständige Alben, Seltenheiten) geben %s mehr Rubine.",
	["The achievements of the expertise, of the seals and of the restorations give %s more experience and rubies."] = "Die Erfolge für Begutachtung, Siegel und Restaurierungen geben %s mehr Erfahrung und Rubine.",
	["The achievements of the trades, of the contracts and of the reseller give %s more experience and rubies."] = "Die Erfolge für Tausch, Verträge und den Wiederverkäufer geben %s mehr Erfahrung und Rubine.",
	["The appraisal of your cards costs %s fewer rubies."] = "Die Begutachtung deiner Karten kostet %s weniger Rubine.",
	["The boosters of this album one after the other, ten at most, then all their cards on the screen."] = "Die Booster dieses Albums nacheinander, höchstens zehn, dann alle ihre Karten auf dem Bildschirm.",
	["The boosters to choose and the displays bought with rubies cost %s less."] = "Mit Rubinen gekaufte Booster zur Wahl und Displays kosten %s weniger.",
	["The bosses of the dungeons and the raids give %s more points to their booster bar."] = "Die Bosse der Dungeons und Schlachtzüge geben ihrer Boosterleiste %s Punkte mehr.",
	["The bosses of the raids fill their booster bar %s more."] = "Die Bosse der Schlachtzüge füllen ihre Boosterleiste um %s schneller.",
	["The bosses of the raids give you their card %s more often."] = "Die Bosse der Schlachtzüge geben dir ihre Karte %s öfter.",
	["The bounties of the week and the heads with a price of the front give a %s chance of one more booster to choose."] = "Die Kopfgelder der Woche und die Köpfe mit Kopfgeld der Front geben eine Chance von %s auf einen zusätzlichen Booster zur Wahl.",
	["The bounties of the week of the battlemaster give one more booster to choose %s of the time."] = "Die Kopfgelder der Woche beim Kampfmeister geben in %s der Fälle einen zusätzlichen Booster zur Wahl.",
	["The cards found on bosses come thunderforged %s of the time."] = "Bei Bossen gefundene Karten sind in %s der Fälle donnergeschmiedet.",
	["The cards found on the bosses of the raids come titanforged %s of the time."] = "Bei Schlachtzugsbossen gefundene Karten sind in %s der Fälle titanengeschmiedet.",
	["The cards of your PvP album become thunderforged %s victories sooner, and titanforged %s sooner."] = "Die Karten deines PvP-Albums werden %s Siege früher donnergeschmiedet und %s früher titanengeschmiedet.",
	["The cards of your boosters give %s more experience, twice as much for an epic card or better."] = "Die Karten deiner Booster geben %s mehr Erfahrung, doppelt so viel bei einer epischen Karte oder besser.",
	["The cards you find on elites and bosses come forged %s more often."] = "Die Karten, die du bei Elitegegnern und Bossen findest, sind %s öfter geschmiedet.",
	["The cases come %s more often."] = "Kisten kommen %s öfter.",
	["The choice is for good: changing your specialization later asks for a reconversion contract, paid in rubies (the first one is offered)."] = "Die Wahl ist endgültig: Ein späterer Wechsel der Spezialisierung erfordert einen Umschulungsvertrag, in Rubinen bezahlt (der erste ist geschenkt).",
	["The creature marked"] = "Die markierte Kreatur",
	["The creatures of your level or above fill your booster bar of the world %s more."] = "Kreaturen deiner Stufe oder höher füllen deine Boosterleiste der Welt um %s schneller.",
	["The elites of the dungeons and the raids give %s more points to their booster bar (0.5 without it)."] = "Die Elitegegner der Dungeons und Schlachtzüge geben ihrer Boosterleiste %s Punkte mehr (0,5 ohne dieses Talent).",
	["The first elite of the hour"] = "Erster Elitegegner der Stunde",
	["The first elite you defeat each hour gives you its card twice as often."] = "Der erste Elitegegner, den du in jeder Stunde besiegst, gibt dir seine Karte doppelt so oft.",
	["The guard of the week (past it, the rubies of the reseller and of the talents count for a quarter) is raised by %s."] = "Die Wochengrenze (darüber zählen die Rubine vom Wiederverkäufer und von den Talenten nur zu einem Viertel) steigt um %s.",
	["The innkeeper's bet takes 3 copies instead of 2, but the card of the rarity above comes twice as often."] = "Die Wette des Gastwirts braucht 3 Exemplare statt 2, aber die Karte der höheren Seltenheit kommt doppelt so oft.",
	["The innkeeper's bet takes one copy only, but one more card wins nothing."] = "Die Wette des Gastwirts braucht nur ein Exemplar, aber eine Karte mehr gewinnt nichts.",
	["The innkeepers you are a regular of tell you two rumors a day instead of one."] = "Die Gastwirte, bei denen du Stammkunde bist, erzählen dir zwei Gerüchte pro Tag statt einem.",
	["The keeper of the archives of Dalaran: appraises, seals, restores and shows. A perfect card is worth a thousand copies."] = "Der Hüter der Archive von Dalaran: begutachtet, versiegelt, restauriert und stellt aus. Eine perfekte Karte ist tausend Exemplare wert.",
	["The keys of the cases cost %s fewer rubies."] = "Die Schlüssel der Kisten kosten %s weniger Rubine.",
	["The king of the black market of Booty Bay: the reseller, the other players and the contracts, always a ruby ahead."] = "Der König des Schwarzmarkts von Beutebucht: der Wiederverkäufer, die anderen Spieler und die Verträge, immer einen Rubin voraus.",
	["The last boss of a dungeon draws its card a second time when it did not give it."] = "Der letzte Boss eines Dungeons zieht seine Karte ein zweites Mal, wenn er sie nicht gegeben hat.",
	["The places discovered, the steps of quests and the quests turned in fill your booster bar of the world %s more."] = "Entdeckte Orte, Questschritte und abgegebene Quests füllen deine Boosterleiste der Welt um %s schneller.",
	["The player of the Darkmoon Faire: the boosters, the displays, the bets of the innkeepers and the cases. More risk, more thrills."] = "Der Spieler des Dunkelmond-Jahrmarkts: Booster, Displays, Kisten und die Wetten der Gastwirte. Mehr Risiko, mehr Nervenkitzel.",
	["The protective cases cost %s fewer rubies."] = "Die Schutzhüllen kosten %s weniger Rubine.",
	["The purifications of the Master Priests cost %s fewer rubies."] = "Die Reinigungen der Priesterlehrer kosten %s weniger Rubine.",
	["The quests of the collector of contracts give you %s more rubies."] = "Die Quests des Sammlers zu Verträgen geben dir %s mehr Rubine.",
	["The quests of the collector of creatures, of elites, of dungeons and of PvP give %s more experience."] = "Die Quests des Sammlers zu Kreaturen, Elitegegnern, Dungeons und PvP geben %s mehr Erfahrung.",
	["The quests of the collector of dungeons, of raids and of PvP give you %s more rubies."] = "Die Quests des Sammlers zu Dungeons, Schlachtzügen und PvP geben dir %s mehr Rubine.",
	["The quests of the collector of gathering, of the inns and of new cards give %s more experience."] = "Die Quests des Sammlers rund ums Sammeln, um die Gasthäuser und um neue Karten geben %s mehr Erfahrung.",
	["The quests of the collector: boosters to choose, experience and rubies."] = "Die Quests des Sammlers: Booster zur Wahl, Erfahrung und Rubine.",
	["The reseller buys back your copies %s dearer."] = "Der Wiederverkäufer kauft deine Exemplare %s teurer zurück.",
	["The reseller buys back your thunderforged and titanforged copies %s dearer."] = "Der Wiederverkäufer kauft deine donner- und titanengeschmiedeten Exemplare %s teurer zurück.",
	["The reseller has %s more cards for sale each day."] = "Der Wiederverkäufer hat jeden Tag %s Karten mehr im Angebot.",
	["The reseller of the vendors of general goods sells displays: 16 boosters of an album."] = "Der Wiederverkäufer bei den Gemischtwarenhändlern verkauft Displays: 16 Booster eines Albums.",
	["The reseller sells you his thunderforged and titanforged cards %s cheaper."] = "Der Wiederverkäufer verkauft dir seine donner- und titanengeschmiedeten Karten %s günstiger.",
	["The restorations take %s less time."] = "Restaurierungen brauchen %s weniger Zeit.",
	["The rubies of your levels and of your quests of the month: +%s."] = "Die Rubine aus deinen Stufen und deinen Monatsquests: +%s.",
	["The seals of the Master Warlocks have a %s chance to go up a rank."] = "Die Siegel der Hexenmeisterlehrer steigen mit einer Chance von %s um einen Rang.",
	["The surveyor of the Explorers' League: the places, the gathering, the inns and their rumors fill the albums of the zones. Strong from the first levels."] = "Der Landvermesser der Forscherliga: Orte, Sammeln, Gasthäuser und ihre Gerüchte füllen die Alben der Gebiete. Stark ab den ersten Stufen.",
	["The talents of the Cartographer and of the Bounty Hunter change these chances."] = "Die Talente des Kartographen und des Kopfgeldjägers ändern diese Chancen.",
	["The talents of the Smuggler: Black Market, Special Order, Pawnbroker."] = "Die Talente des Schmugglers: Schwarzmarkt, Sonderbestellung, Pfandleiher.",
	["The thunderforged and titanforged cards of your boosters give %s more experience."] = "Die donner- und titanengeschmiedeten Karten deiner Booster geben %s mehr Erfahrung.",
	["The tooltip of a card tells you what the reseller gives you for a copy, and what he sells it for."] = "Der Tooltip einer Karte zeigt dir, was der Wiederverkäufer dir für ein Exemplar gibt und wofür er es verkauft.",
	["The trades with your guild do not count among the 5 players a day of Handshake, and give twice as much."] = "Tauschgeschäfte mit deiner Gilde zählen nicht zu den 5 Spielern pro Tag von Handschlag und geben doppelt so viel.",
	["This character is a reroll: a quarter of everything, kept here until level %d."] = "Dieser Charakter ist ein Nebencharakter: ein Viertel von allem, hier aufbewahrt bis Stufe %d.",
	["This character is a reroll: it opens no booster, display or case until level %d."] = "Dieser Charakter ist ein Nebencharakter: Er öffnet bis Stufe %d keine Booster, Displays oder Kisten.",
	["This character is a reroll: it opens no booster, display or case. Open them with your main character, %s, or with this one from level %d."] = "Dieser Charakter ist ein Nebencharakter: Er öffnet keine Booster, Displays oder Kisten. Öffne sie mit deinem Hauptcharakter, %s, oder mit diesem ab Stufe %d.",
