	["A card of the stall of the reseller at the price he buys it back, a summit of the Smuggler."] = "Eine Karte aus der Auslage des Wiederverkäufers zu dem Preis, zu dem er sie zurückkauft, dank einem Gipfel des Schmugglers.",
	["Master Restorer"] = "Meisterrestaurator",
	["A copy restored to 10 by a Masterpiece, a summit of the Archivist."] = "Ein Exemplar auf 10 restauriert dank Meisterwerk, einem Gipfel des Archivars.",
	["A 10 from an appraisal of the Grand Conservator, a summit of the Archivist."] = "Eine 10 bei einer Begutachtung dank Großkonservator, einem Gipfel des Archivars.",
