	["Contract of the Week"] = "Контракт недели",
	["Darkmoon Fortune"] = "Удача Новолуния",
	["Darkmoon Wheel"] = "Колесо Новолуния",
	["Darkmoon Wheel: %s, to put in the album you want (the inventory, Boosters)."] = "«Колесо Новолуния»: %s, в любой альбом («Инвентарь», «Бустеры»).",
	["Death Halloo"] = "Победный клич",
	["Deep Pockets"] = "Глубокие карманы",
	["Deleted before level %d, it takes its chest with it."] = "Если удалить его до %d уровня, сундук пропадёт вместе с ним.",
	["Display Chest"] = "Щедрая коробка",
	["Display Chest: a booster more!"] = "«Щедрая коробка»: ещё один бустер!",
	["Distant Trade"] = "Дальняя торговля",
	["Double or Nothing"] = "Всё или ничего",
	["Double or Nothing can bet a whole display: three more boosters, or three fewer."] = "«Всё или ничего» может поставить на кон целую коробку: на три бустера больше или на три меньше.",
	["Double or Nothing leans your way: one more card won (rank 1), one card fewer lost (rank 2), a 60 %% chance to win (rank 3)."] = "«Всё или ничего» склоняется в вашу пользу: при выигрыше на одну карту больше (ранг 1), при проигрыше теряется на одну карту меньше (ранг 2), шанс выигрыша 60 %% (ранг 3).",
	["Double or Nothing lost, but Nerves of Steel: it costs nothing."] = "Проигрыш во «Всё или ничего», но благодаря «Стальным нервам» без потерь.",
	["Double or Nothing makes you lose no card any more, but wins you one only."] = "«Всё или ничего» больше не отнимает у вас карт, но выигрыш составляет лишь одну карту.",
	["Double or Nothing recharges in %s."] = "Восстановление «Всё или ничего»: %s.",
	["Double or Nothing won on a booster of a dungeon or a raid: one more card."] = "Выигрыш во «Всё или ничего» на бустере подземелья или рейда: ещё одна карта.",
	["Double or Nothing won on a booster of a zone: 100 rubies more."] = "Выигрыш во «Всё или ничего» на бустере зоны: ещё 100 рубинов.",
	["Double or Nothing: a %s chance that a bet lost costs nothing."] = "«Всё или ничего»: с шансом %s проигранная ставка ничего не стоит.",
	["Double or Nothing: lost, %d cards fewer."] = "«Всё или ничего»: проигрыш, карт меньше на %d.",
	["Double or Nothing: lost, but Nerves of Steel kept the boosters."] = "«Всё или ничего»: проигрыш, но «Стальные нервы» сохранили бустеры.",
	["Double or Nothing: lost, one card fewer."] = "«Всё или ничего»: проигрыш, на одну карту меньше.",
	["Double or Nothing: lost, three boosters fewer."] = "«Всё или ничего»: проигрыш, на три бустера меньше.",
	["Double or Nothing: nothing won, nothing lost."] = "«Всё или ничего»: ни выигрыша, ни проигрыша.",
	["Double or Nothing: the bet is taken back."] = "«Всё или ничего»: ставка отозвана.",
	["Double or Nothing: won, %d cards more!"] = "«Всё или ничего»: выигрыш, карт больше на %d!",
	["Double or Nothing: won, one card more!"] = "«Всё или ничего»: выигрыш, на одну карту больше!",
	["Double or Nothing: won, three boosters more!"] = "«Всё или ничего»: выигрыш, на три бустера больше!",
	["Double or Nothing: your next booster is the bet."] = "«Всё или ничего»: на кону ваш следующий бустер.",
	["Double or Nothing: your next booster or display is the bet."] = "«Всё или ничего»: на кону ваш следующий бустер или коробка.",
	["Each album of a zone completed gives you %s rubies."] = "Каждый собранный альбом зоны приносит вам рубины: %s.",
	["Each bet won at an innkeeper gives you %s rubies, each case opened %s."] = "Каждое выигранное у хозяина таверны пари приносит вам рубины: %s, каждый открытый ящик: %s.",
	["Each card appraised 8 or better gives you %s rubies."] = "Каждая карта с оценкой 8 и выше приносит вам рубины: %s.",
	["Each card appraised gives you %s experience, three times as much for a 9 or a 10."] = "Каждая оценённая карта приносит вам опыт: %s, втрое больше за 9 или 10.",
	["Each card bought from the reseller gives you back %s of its price in rubies."] = "Каждая карта, купленная у перекупщика, возвращает вам %s её цены в рубинах.",
	["Each collector level: a booster to choose, for the album you want."] = "Каждый уровень коллекционера: бустер на выбор, в любой альбом.",
	["Each collector who looks at your showcase gives you 5 rubies (20 visitors a day at most)."] = "Каждый коллекционер, посмотревший вашу витрину, приносит вам 5 рубинов (не больше 20 посетителей в день).",
	["Each contract signed gives you %s experience."] = "Каждый подписанный договор приносит вам опыт: %s.",
	["Each day, a target is named to you: an elite or a rare of a zone of your level whose card you are missing. Defeat it and its card is given to you. The first time: an achievement and a title of prestige."] = "Каждый день вам называют цель: элитного или редкого противника из зоны вашего уровня, чьей карты у вас нет. Победите его, и его карта достанется вам. В первый раз: достижение и престижное звание.",
	["Each day, among the cards the reseller sells, one is surely missing from your albums."] = "Каждый день среди карт, которые продаёт перекупщик, обязательно есть одна, которой нет в ваших альбомах.",
	["Each day, spin the wheel: nothing (40 %%), 150 rubies (30 %%), a booster of a zone (22 %%), two boosters of a zone (6 %%) or a booster of a dungeon (2 %%). The first time it stops on the booster of a dungeon: an achievement and a title of prestige."] = "Каждый день крутите колесо: ничего (40 %%), 150 рубинов (30 %%), бустер зоны (22 %%), два бустера зоны (6 %%) или бустер подземелья (2 %%). Когда оно впервые остановится на бустере подземелья: достижение и престижное звание.",
	["Each day, you can order from the reseller a card you are missing, epic at most, at its full price. The first time: an achievement and a title of prestige."] = "Каждый день вы можете заказать у перекупщика недостающую карту, не выше эпической, по полной цене. В первый раз: достижение и престижное звание.",
	["Each day, your first 5 boosters opened: a %s chance that one of their cards goes up a rarity (epic at most)."] = "Каждый день ваши первые 5 открытых бустеров: с шансом %s одна из их карт поднимается на ступень редкости (не выше эпической).",
	["Each day, your first quest turned in in each zone fills its bar with %s more points."] = "Каждый день ваше первое сданное задание в каждой зоне даёт её шкале больше очков: +%s.",
	["Each day, your first victory over a creature whose card you are missing (rare at most), in a zone where you have less than three quarters of the cards, gives you its card. The first time: an achievement and a title of prestige."] = "Каждый день ваша первая победа над существом, чьей карты у вас нет (не выше редкой), в зоне, где у вас меньше трёх четвертей карт, приносит вам его карту. В первый раз: достижение и престижное звание.",
	["Each elite or rare whose card you find gives you %s rubies."] = "Каждый элитный или редкий противник, чью карту вы находите, приносит вам рубины: %s.",
	["Each herb, ore, skin or fish you gather gives %s points to your booster bar of the world (a creature gives 2)."] = "Каждый сбор травы, руды, шкур или рыбы: +%s к шкале бустера мира (существо даёт 2).",
	["Each honorable kill fills your booster bar of the world with %s points."] = "Каждая почётная победа: +%s к шкале бустера мира.",
	["Each new combatant certified in your PvP album gives you %s rubies."] = "Каждый новый боец, заверенный в вашем PvP-альбоме, приносит вам рубины: %s.",
	["Each new visa of your travel passport gives you %s rubies and %s experience."] = "Каждая новая виза в дорожном паспорте приносит вам рубины (%s) и опыт (%s).",
	["Each rare you defeat fills your booster bar of the world with %s points."] = "Каждое побеждённое вами редкое существо: +%s к шкале бустера мира.",
	["Each thing gathered has a %s chance to give you 25 rubies."] = "Каждый собранный ресурс с шансом %s приносит вам 25 рубинов.",
	["Each trade confirmed gives you 10 rubies (5 trades a day)."] = "Каждый подтверждённый обмен приносит вам 10 рубинов (5 обменов в день).",
	["Each week you open 50 boosters or more: %s rubies."] = "Каждая неделя, в которую вы открываете не меньше 50 бустеров, приносит вам рубины: %s.",
	["Each week, the first last boss of a dungeon or boss of a raid you defeat gives you one more booster of its album."] = "Каждую неделю первый побеждённый вами последний босс подземелья или босс рейда даёт вам ещё один бустер своего альбома.",
	["Each week, when you hold more than 20 000 rubies, you earn %s of them (300 at most for each rank)."] = "Каждую неделю, если у вас больше 20 000 рубинов, вы получаете %s от этой суммы (не больше 300 за каждый ранг).",
	["Each week, your best appraised copy gives you %s rubies (three times as many for a 10)."] = "Каждую неделю ваша лучшая оценённая копия приносит вам рубины: %s (втрое больше за 10).",
	["Each week, your first booster opened has one chance in ten to become a booster of legend: 5 cards epic or better, one of them legendary. The first time: an achievement and a title of prestige."] = "Каждую неделю ваш первый открытый бустер с шансом один из десяти становится легендарным: 5 карт эпической редкости или лучше, одна из них легендарная. В первый раз: достижение и престижное звание.",
	["Enchanter's Patience"] = "Терпение зачаровывателя",
	["Endless Hunt"] = "Бесконечная охота",
