	["Gambler's Eye: %s"] = "«Глаз игрока»: %s",
	["Gladiator"] = "Гладиатор",
	["Glance"] = "Беглый взгляд",
	["Glance also shows the four grades (rank 1), then tells the true grade of a restored copy without paying its appraisal again (rank 2)."] = "«Беглый взгляд» показывает и четыре частные оценки (ранг 1), а затем истинную оценку восстановленной копии без повторной оплаты экспертизы (ранг 2).",
	["Glance also works on the seals: you see their rank before you pay."] = "«Беглый взгляд» действует и на печати: вы видите их ранг до оплаты.",
