	["Morning Dew"] = "아침 이슬",
	["Mounted Heads"] = "머리 박제",
	["Museum Showcase"] = "박물관 진열장",
	["Necklace of Teeth"] = "송곳니 목걸이",
	["Nerves of Steel"] = "강철 신경",
	["No album here"] = "이곳엔 앨범 없음",
	["No card you are missing in the albums he sells."] = "그가 파는 앨범에는 아직 못 구한 카드가 없습니다.",
	["No copy sold in the last 3 days."] = "최근 3일 동안 판 카드가 없습니다.",
	["No talent to use yet: the third tier of your tree holds one."] = "아직 사용할 특성이 없습니다: 트리의 3단계에 하나 있습니다.",
	["Nomad"] = "방랑자",
	["Nose for Cases"] = "상자 탐지",
