	["Your restorations have a %s chance to gain half a point more."] = "복원이 %s 확률로 0.5점 더 향상됩니다.",
	["Your rubies: %s. It costs you nothing."] = "보유 루비: %s. 비용이 들지 않습니다.",
	["Your showcase shows two more cards."] = "진열장에 카드가 2장 더 전시됩니다.",
	["Your talents on it: %s."] = "이 복원에 적용되는 특성: %s.",
	["Your talents were given back: %d points to place again as you like, free of charge (/curator talents)."] = "특성이 초기화되었습니다: %d포인트를 원하는 대로 무료로 다시 배분하세요 (/curator talents).",
	["offered"] = "무료",
	["Pathfinder"] = "길잡이",
